"""Analyst-style dilution summary paragraph, generated by Claude."""
import json
import logging

from app.services.ai.llm import complete_text

logger = logging.getLogger(__name__)

NO_EVENTS = "No significant recent dilution events or overhangs were detected in the analyzed filings."

SYSTEM = """You are a senior financial analyst providing a brief, executive summary of dilution risks for a single stock ticker.

Write a professional 3-4 sentence paragraph that reads like a human analyst's report.

CRITICAL RULES:
- Synthesize and contextualize the numbers naturally into a cohesive narrative. DO NOT just list or copy the exact dollar amounts as raw data.
- Frame the summary as an analyst discussing the overall risk profile and recent financial activity.
- Explain *what the dilution data means* for the current state of the company.
- If 'status' is 'Active', the dilution is CURRENTLY occurring or has just formally closed.
- If 'status' is 'Potential', it is a future overhang (like a shelf offering) but not actively selling yet.
- Trust the structured 'amount', 'category', and 'status' fields.
- If no events are present, state "No significant recent dilution events or overhangs were detected in the latest filings."

Return only the paragraph."""


class DilutionSummarizer:
    async def summarize(self, ticker: str, events: list) -> str:
        if not events:
            return NO_EVENTS
        prompt = (
            f"Ticker: {ticker}\n\nStructured dilution events/instruments found in SEC filings:\n"
            f"{json.dumps(events, indent=2, default=str)}"
        )
        try:
            return (await complete_text(SYSTEM, prompt)).strip()
        except Exception as e:  # noqa: BLE001
            logger.error(f"Error generating dilution summary: {e}")
            return "Unable to generate dilution summary at this time."
